define("mod_questionnaire/survey_inputs",[],(function(){var otherCheck=function(input){var name=input.name,idx=name.indexOf("o");if(idx<0){return}var other=name.slice(idx+1),bracket=other.indexOf("]");if(bracket!==-1){other=other.slice(0,bracket)}var form=document.getElementById("phpesp_response");if(!form){return}for(var i=0;i<form.elements.length;i++){if(form.elements[i].value===other){form.elements[i].checked=true;break}}},rateUncheck=function(radio){var name=radio.name,value=radio.value,underscoreAt=name.indexOf("_");if(underscoreAt<0){return}var colName=name.substr(0,underscoreAt),buttons=document.getElementsByTagName("input");for(var i=0;i<buttons.length;i++){var button=buttons[i];if(button.type==="radio"&&button.name!==name&&button.value===value&&button.name.substr(0,underscoreAt)===colName){button.checked=false}}};return{init:function(){var form=document.getElementById("phpesp_response");if(!form){return}form.addEventListener("click",(function(event){var target=event.target;if(!target||target.tagName!=="INPUT"){return}if(target.hasAttribute("data-questionnaire-other-check")){otherCheck(target)}else if(target.hasAttribute("data-questionnaire-rate-uncheck")){rateUncheck(target)}}))}}}));
